mapper.insert:
insert into parent(
	parent_no,
	account_no
) 
values(
	#{parentNo},
	#{accountNo}
)

mapper.select:
select p_page.*, ps.student_no, sa.account_name as student_name, ps.relationship from ( select * from ( select inner_table.*, ROWNUM as rn from ( select p.parent_no, a.account_no, a.account_id, a.account_name, a.account_phone, a.account_status, a.account_birth, a.account_utime, a.account_type from parent p join account a on p.account_no = a.account_no
order by p.parent_no desc ) inner_table
where ROWNUM <= #{endRow}
)
where rn >= #{beginRow}
) p_page left join parent_student ps on p_page.parent_no = ps.parent_no left join student s on ps.student_no = s.student_no left join account sa on s.account_no = sa.account_no order by p_page.parent_no desc, ps.student_no asc
